public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();

    int[][] boxes = new int[N][2];
    int[] B = new int[M];

    for(int i = 0; i < N; i++) {
        boxes[i][0] = sc.nextInt(); // candies
        boxes[i][1] = sc.nextInt(); // price
    }
    for(int i = 0; i < M; i++) {
        B[i] = sc.nextInt();
    }

    Arrays.sort(boxes, (a, b) -> Integer.compare(a[0], b[0]));
    Arrays.sort(B);

    long totalPayment = 0;
    int j = 0;

    for (int i = 0; i < M; i++) {
        while (j < N && boxes[j][0] < B[i]) {
            j++;
        }
        if (j == N) {
            System.out.println(-1);
            return;
        }
        totalPayment += boxes[j][1];
        j++;
    }

    System.out.println(totalPayment);
}
